import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Dashboard(props) {
  const [scholarships, setScholarships] = useState([]);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  const API = process.env.REACT_APP_API_BASE_URL;

  useEffect(() => {
    const role = localStorage.getItem("designation");
    const token = localStorage.getItem("token");

    if (role !== "admin") {
      setMessage("Access denied: Admins only");
      setLoading(false);
      return;
    }

    const fetchScholarships = async () => {
      try {
        setLoading(true);

        const res = await fetch(`${API}/scholarship/schemes`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        const data = await res.json();

        if (res.ok) {
          setScholarships(data.data || []);
        } else {
          setMessage(data.message || "Failed to fetch scholarships");
        }
      } catch (err) {
        setMessage("Server error while fetching scholarships");
      } finally {
        setLoading(false);
      }
    };

    fetchScholarships();
  }, [API]);

  const handlePostClick = () => {
    navigate("/postscholarship");
  };

  const handleEditClick = (scholarshipId) => {
    navigate(`/editscholarship/${scholarshipId}`);
  };

  const handleApplicantsClick = (scholarshipId) => {
    navigate(`/applications/${scholarshipId}`);
  };

  const handleDeleteClick = async (scholarshipId) => {
    if (!window.confirm("Are you sure you want to delete this scholarship?"))
      return;

    try {
      const token = localStorage.getItem("token");

      const res = await fetch(
        `${API}/scholarship/scheme/${scholarshipId}`,
        {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await res.json();

      if (res.ok) {
        setScholarships((prev) =>
          prev.filter(
            (sch) => sch.scholarship_id !== scholarshipId
          )
        );
        setMessage("Scholarship deleted successfully");
      } else {
        setMessage(data.message || "Failed to delete scholarship");
      }
    } catch (err) {
      setMessage("Server error while deleting scholarship");
    }
  };

  return (
    <div className="container-fluid px-4 py-5">
      <div className="container">

        {message && (
          <div
            className={`alert ${
              message.includes("denied") ||
              message.includes("error") ||
              message.includes("Failed")
                ? "alert-danger"
                : "alert-success"
            }`}
          >
            {message}
          </div>
        )}

        {loading ? (
          <div className="text-center py-5">
            <div className="spinner-border text-primary"></div>
            <p className="mt-2">Loading scholarships...</p>
          </div>
        ) : scholarships.length > 0 ? (
          <div className="card shadow-sm">
            <div className="card-header d-flex justify-content-between">
              <h5>Manage Scholarships</h5>
              <button
                className="btn btn-danger"
                onClick={handlePostClick}
              >
                Post New Scholarship
              </button>
            </div>

            <div className="table-responsive">
              <table className="table table-hover mb-0">
                <thead className="table-light">
                  <tr>
                    <th>#</th>
                    <th>Title</th>
                    <th>Organization</th>
                    <th>Deadline</th>
                    <th>Amount</th>
                    <th>Applicants</th>
                    <th>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {scholarships.map((sch, index) => (
                    <tr key={sch.scholarship_id}>
                      <td>{index + 1}</td>
                      <td>{sch.title}</td>
                      <td>{sch.organization}</td>
                      <td>
                        <span
                          className={`badge ${
                            new Date(sch.deadline) > new Date()
                              ? "bg-success"
                              : "bg-danger"
                          }`}
                        >
                          {new Date(
                            sch.deadline
                          ).toLocaleDateString()}
                        </span>
                      </td>
                      <td>
                        ₹{Number(
                          sch.amount || 0
                        ).toLocaleString()}
                      </td>
                      <td>
                        <span className="badge bg-info">
                          {sch.total_applicants || 0}
                        </span>
                      </td>
                      <td>
                        <button
                          className="btn btn-sm btn-outline-primary me-2"
                          onClick={() =>
                            handleEditClick(
                              sch.scholarship_id
                            )
                          }
                        >
                          Edit
                        </button>

                        <button
                          className="btn btn-sm btn-outline-success me-2"
                          onClick={() =>
                            handleApplicantsClick(
                              sch.scholarship_id
                            )
                          }
                        >
                          Applicants
                        </button>

                        <button
                          className="btn btn-sm btn-outline-danger"
                          onClick={() =>
                            handleDeleteClick(
                              sch.scholarship_id
                            )
                          }
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="text-center py-5">
            <h4>No Scholarships Found</h4>
            <button
              className="btn btn-primary mt-3"
              onClick={handlePostClick}
            >
              Post First Scholarship
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
